import SwiftUI

struct WeatherView: View {
    @EnvironmentObject var store: AppStore
    @State private var showCities = false
    @State private var selectedDay: WeatherDay?
    @State private var detailMetric: Metric?
    @State private var showSettings = false
    enum Metric: String, Identifiable { case humidity, wind, pressure, sunset; var id: String { rawValue }; var title: String { switch self { case .humidity: return "Влажность"; case .wind: return "Ветер"; case .pressure: return "Давление"; case .sunset: return "Закат" } }; var text: String { switch self { case .humidity: return "Влажность — сколько водяного пара в воздухе. Высокая влажность может ощущаться прохладнее и усиливать ощущение духоты."; case .wind: return "Ветер — скорость движения воздуха. При сильном ветре ощущается холоднее, чем показывает термометр."; case .pressure: return "Атмосферное давление — вес воздуха над землёй. Резкие изменения могут влиять на самочувствие."; case .sunset: return "Время заката для выбранного города. После него температура обычно быстро снижается." } } }
    var body: some View { ScrollView(showsIndicators: false) { VStack(spacing: 18) { HStack { Button { showCities = true } label: { HStack(spacing: 10) { Image(systemName: "location.fill").font(.title2).foregroundStyle(.purple); Text(store.selectedCity.name).font(.title.bold()); Image(systemName: "chevron.down").foregroundStyle(.secondary) } }; Spacer(); Button { showSettings = true } label: { Image(systemName: "gearshape.fill").font(.title2).padding(15).background(.ultraThinMaterial, in: Circle()) } }.padding(.horizontal, 22).padding(.top, 12)
            if let weather = store.weather { hero(weather); forecast(weather); metrics(weather) } else { ProgressView().frame(height: 460) }
        }.padding(.bottom, 16) }.sheet(isPresented: $showCities) { CityPickerView() }.sheet(item: $selectedDay) { HourlyWeatherView(day: $0, city: store.selectedCity.name) }.sheet(item: $detailMetric) { metric in MetricInfoView(metric: metric) }.sheet(isPresented: $showSettings) { SettingsView() }.refreshable { await store.refreshWeather() } }
    func hero(_ w: WeatherSnapshot) -> some View { VStack(alignment: .leading, spacing: 14) { HStack { VStack(alignment: .leading) { Text(w.days.first?.summary ?? "Погода").font(.headline).foregroundStyle(.secondary); Text("\(w.current)°").font(.system(size: 78, weight: .bold, design: .rounded)); Text("Ощущается как \(w.feels)°").font(.title3).foregroundStyle(.secondary) }; Spacer(); Image(systemName: w.symbol).symbolRenderingMode(.multicolor).font(.system(size: 82)).shadow(color: .orange.opacity(0.5), radius: 20) }.padding(.horizontal, 22); HStack(spacing: 10) { ActionChip(icon: "🧥", title: w.current < 10 ? "Одевайся тепло" : "Можно легче") { detailMetric = .wind }; ActionChip(icon: "☂️", title: w.current < 12 ? "Возьми зонт" : "Зонт не нужен") { detailMetric = .humidity } } }.padding(.top, 16).padding(.bottom, 10) }
    func forecast(_ w: WeatherSnapshot) -> some View { VStack(alignment: .leading, spacing: 0) { Text("Прогноз на 7 дней").font(.headline).padding(.horizontal, 4).padding(.bottom, 8); ForEach(w.days) { day in Button { selectedDay = day } label: { HStack { Text(day.date.formatted(.dateTime.weekday(.wide))).frame(width: 100, alignment: .leading); Image(systemName: day.symbol).symbolRenderingMode(.multicolor).frame(width: 42); Text(day.summary).font(.subheadline).foregroundStyle(.secondary).lineLimit(1); Spacer(); Text("\(day.min)°").foregroundStyle(.secondary); Text("\(day.max)°").fontWeight(.bold); Image(systemName: "chevron.right").font(.caption).foregroundStyle(.purple) }.padding(.vertical, 13).contentShape(Rectangle()) }.buttonStyle(.plain); if day.id != w.days.last?.id { Divider().opacity(0.25) } } }.padding(18).background(.ultraThinMaterial, in: RoundedRectangle(cornerRadius: 26)).padding(.horizontal, 22) }
    func metrics(_ w: WeatherSnapshot) -> some View { HStack { MetricButton(icon: "drop.fill", value: "\(w.humidity)%", label: "Влажность", color: .cyan) { detailMetric = .humidity }; MetricButton(icon: "wind", value: "\(w.wind) км/ч", label: "Ветер", color: .mint) { detailMetric = .wind }; MetricButton(icon: "gauge.with.dots.needle.67percent", value: "\(w.pressure)", label: "Давление", color: .purple) { detailMetric = .pressure }; MetricButton(icon: "sunset.fill", value: "16:42", label: "Закат", color: .orange) { detailMetric = .sunset } }.padding(.horizontal, 22) }
}
struct ActionChip: View { let icon: String; let title: String; let action: () -> Void; var body: some View { Button(action: action) { HStack { Text(icon); Text(title).font(.subheadline.weight(.semibold)); Spacer(); Image(systemName: "chevron.right").foregroundStyle(.purple) }.padding(15).frame(maxWidth: .infinity).background(.ultraThinMaterial, in: Capsule()) } }
struct MetricButton: View { let icon: String; let value: String; let label: String; let color: Color; let action: () -> Void; var body: some View { Button(action: action) { VStack(spacing: 5) { Image(systemName: icon).foregroundStyle(color); Text(value).font(.subheadline.weight(.bold)); Text(label).font(.caption2).foregroundStyle(.secondary) }.frame(maxWidth: .infinity) }.buttonStyle(.plain) } }
struct HourlyWeatherView: View { let day: WeatherDay; let city: String; var body: some View { NavigationStack { List(day.hours, id: \.0) { hour in HStack { Text(hour.0).frame(width: 58, alignment: .leading); Image(systemName: hour.2).symbolRenderingMode(.multicolor); Text("\(hour.1)°"); Spacer(); Text(day.summary).foregroundStyle(.secondary) } }.navigationTitle("\(city) · \(day.date.formatted(.dateTime.weekday(.wide)))").navigationBarTitleDisplayMode(.inline) } }
struct MetricInfoView: View { let metric: WeatherView.Metric; var body: some View { VStack(spacing: 18) { Image(systemName: "info.circle.fill").font(.system(size: 52)).foregroundStyle(.purple); Text(metric.title).font(.title.bold()); Text(metric.text).font(.body).multilineTextAlignment(.center).foregroundStyle(.secondary); Spacer() }.padding(28).presentationDetents([.height(290)]) } }
struct CityPickerView: View { @EnvironmentObject var store: AppStore; @Environment(\.dismiss) var dismiss; @State private var query = ""; @State private var cityName = ""; var filtered: [WeatherCity] { store.savedCities.filter { query.isEmpty || $0.name.localizedCaseInsensitiveContains(query) } }; var body: some View { NavigationStack { List { Section("Мои города") { ForEach(filtered) { city in Button { store.selectedCityID = city.id; dismiss(); Task { await store.refreshWeather() } } label: { HStack { Image(systemName: "location.fill").foregroundStyle(.purple); Text(city.name); Spacer(); if city.id == store.selectedCityID { Image(systemName: "checkmark").foregroundStyle(.orange) } } } }.onDelete { offsets in store.savedCities.remove(atOffsets: offsets) }; Section("Добавить") { TextField("Например, Варшава", text: $cityName); Button("Добавить город") { let query = cityName.trimmingCharacters(in: .whitespacesAndNewlines); guard !query.isEmpty else { return }; Task { do { let city = try await WeatherService.searchCity(query); store.savedCities.append(city); store.selectedCityID = city.id; cityName = ""; dismiss(); await store.refreshWeather() } catch { store.notice = "Город не найден" } } } } }.searchable(text: $query).navigationTitle("Города").toolbar { ToolbarItem(placement: .cancellationAction) { Button("Готово") { dismiss() } } } } }
